1	// POST /groups/:id/import: records a list of expenses and payments for a group in one go, all of them or none.
2	// Same handler contract as lib/groups.mjs: it returns a new store instead of changing the one it gets.
3	import { NOT_FOUND, findGroup } from './groups.mjs'
4	import { balances, expenseView, paymentView } from './ledger.mjs'
5	import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'
6	
7	const BODY_FIELDS = ['entries', 'dry_run', 'skip_recorded']
8	const MIN_ENTRIES = 1
9	const MAX_ENTRIES = 50
10	const ENTRY_FIELDS = {
11	  expense: ['type', 'description', 'payer', 'amount', 'split'],
12	  payment: ['type', 'from', 'to', 'amount'],
13	}
14	
15	const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v)
16	
17	// Thrown while reviewing an entry: rule is the first import rule the entry breaks.
18	class BrokenRule extends Error {
19	  constructor(rule) {
20	    super(rule)
21	    this.rule = rule
22	  }
23	}
24	
25	// Runs parse and returns its value, or throws BrokenRule(rule) when parse throws a ValidationError.
26	function check(rule, parse) {
27	  try {
28	    return parse()
29	  } catch (err) {
30	    if (err instanceof ValidationError) throw new BrokenRule(rule)
31	    throw err
32	  }
33	}
34	
35	// Two expenses are the same when payer, amount in cents and description (trimmed, lower case) match.
36	const expenseKey = ({ payer, amount, description }) =>
37	  JSON.stringify([payer, amount, description.trim().toLowerCase()])
38	
39	// A boolean body flag: false when its key is absent, otherwise it must be true or false.
40	function parseFlag(body, name) {
41	  if (!Object.hasOwn(body, name)) return false
42	  if (typeof body[name] !== 'boolean') throw new ValidationError(`${name} must be true or false`)
43	  return body[name]
44	}
45	
46	function parseBody(body) {
47	  const unknown = Object.keys(body).find(key => !BODY_FIELDS.includes(key))
48	  if (unknown !== undefined) throw new ValidationError(`unknown field ${unknown}`)
49	  const { entries } = body
50	  if (!Array.isArray(entries) || entries.length < MIN_ENTRIES || entries.length > MAX_ENTRIES) {
51	    throw new ValidationError(`entries must be an array of ${MIN_ENTRIES} to ${MAX_ENTRIES} items`)
52	  }
53	  return { entries, dryRun: parseFlag(body, 'dry_run'), skipRecorded: parseFlag(body, 'skip_recorded') }
54	}
55	
56	// The fields of one entry as { kind, fields }, or throws BrokenRule with the first rule it breaks, from
57	// not-an-object to bad-split (bad-amount for a payment).
58	function parseEntry(entry, group) {
59	  if (!isObject(entry)) throw new BrokenRule('not-an-object')
60	  const kind = entry.type
61	  if (kind !== 'expense' && kind !== 'payment') throw new BrokenRule('bad-type')
62	  if (Object.keys(entry).some(key => !ENTRY_FIELDS[kind].includes(key))) throw new BrokenRule('unknown-field')
63	  if (kind === 'expense') {
64	    const fields = {
65	      description: check('bad-description', () => parseDescription(entry.description)),
66	      payer: check('bad-payer', () => parseMember(entry.payer, group.members, 'bad payer')),
67	      amount: check('bad-amount', () => parseAmount(entry.amount)),
68	      split: check('bad-split', () => parseSplit(entry.split, group.members)),
69	    }
70	    return { kind, fields }
71	  }
72	  const from = check('bad-from', () => parseMember(entry.from, group.members, 'bad from'))
73	  const to = check('bad-to', () => parseMember(entry.to, group.members, 'bad to'))
74	  if (to === from) throw new BrokenRule('bad-to')
75	  return { kind, fields: { from, to, amount: check('bad-amount', () => parseAmount(entry.amount)) } }
76	}
77	
78	// Sorts every entry into parsed (with its kind and fields), skipped indexes and problems, in entry order.
79	function review(entries, group, state, skipRecorded) {
80	  const recorded = new Set(state.expenses.filter(e => e.group === group.id).map(expenseKey))
81	  const seen = new Set()
82	  const parsed = []
83	  const skipped = []
84	  const problems = []
85	  entries.forEach((entry, index) => {
86	    let result
87	    try {
88	      result = parseEntry(entry, group)
89	    } catch (err) {
90	      if (!(err instanceof BrokenRule)) throw err
91	      problems.push({ index, rule: err.rule })
92	      return
93	    }
94	    if (result.kind === 'expense') {
95	      const key = expenseKey(result.fields)
96	      const isDuplicate = seen.has(key)
97	      seen.add(key)
98	      if (isDuplicate) return problems.push({ index, rule: 'duplicate' })
99	      if (recorded.has(key)) {
100	        if (skipRecorded) return skipped.push(index)
101	        return problems.push({ index, rule: 'already-recorded' })
102	      }
103	    }
104	    parsed.push(result)
105	  })
106	  return { parsed, skipped, problems }
107	}
108	
109	export function importEntries({ state, params, body }) {
110	  const group = findGroup(state, params[0])
111	  if (!group) return NOT_FOUND
112	  const { entries, dryRun, skipRecorded } = parseBody(body)
113	  const { parsed, skipped, problems } = review(entries, group, state, skipRecorded)
114	  if (problems.length > 0) return { status: 422, body: { error: 'import rejected', problems } }
115	
116	  const expenses = []
117	  const payments = []
118	  let { nextExpenseId, nextPaymentId } = state
119	  for (const { kind, fields } of parsed) {
120	    if (kind === 'expense') expenses.push({ id: nextExpenseId++, group: group.id, ...fields })
121	    else payments.push({ id: nextPaymentId++, group: group.id, ...fields })
122	  }
123	  const next = {
124	    ...state,
125	    expenses: [...state.expenses, ...expenses],
126	    payments: [...state.payments, ...payments],
127	    nextExpenseId,
128	    nextPaymentId,
129	  }
130	  const reply = {
131	    status: dryRun ? 200 : 201,
132	    body: {
133	      expenses: expenses.map(expenseView),
134	      payments: payments.map(paymentView),
135	      skipped,
136	      balances: balances(next, group),
137	    },
138	  }
139	  // A dry run, or an import whose entries were all skipped, writes nothing.
140	  return dryRun || parsed.length === 0 ? reply : { ...reply, state: next }
141	}
