1	import { mkdtempSync, rmSync } from 'node:fs'
2	import { tmpdir } from 'node:os'
3	import { join } from 'node:path'
4	import { createApp } from '../server.mjs'
5	
6	// A data file in a fresh temp folder; cleanup() deletes the folder.
7	export function tempDataFile() {
8	  const dir = mkdtempSync(join(tmpdir(), 'split-test-'))
9	  return { file: join(dir, 'groups.json'), cleanup: () => rmSync(dir, { recursive: true, force: true }) }
10	}
11	
12	// Starts the app on a free port. call(method, path, body) sends one request; stop() closes the server.
13	export async function startApp(dataFile) {
14	  const server = createApp(dataFile)
15	  await new Promise((resolve, reject) => {
16	    server.once('error', reject)
17	    server.listen(0, '127.0.0.1', resolve)
18	  })
19	  const base = `http://127.0.0.1:${server.address().port}`
20	  return {
21	    call: (method, path, body) => request(base + path, method, body),
22	    stop: () => new Promise(resolve => server.close(resolve)),
23	  }
24	}
25	
26	// Runs fn with a running app on its own data file, then stops it and deletes the file.
27	export async function withApp(fn) {
28	  const data = tempDataFile()
29	  const app = await startApp(data.file)
30	  try {
31	    await fn(app.call)
32	  } finally {
33	    await app.stop()
34	    data.cleanup()
35	  }
36	}
37	
38	async function request(url, method, body) {
39	  const init = { method }
40	  if (body !== undefined) {
41	    init.headers = { 'content-type': 'application/json' }
42	    init.body = typeof body === 'string' ? body : JSON.stringify(body)
43	  }
44	  const res = await fetch(url, init)
45	  const text = await res.text()
46	  const isJson = (res.headers.get('content-type') ?? '').startsWith('application/json')
47	  return { status: res.status, headers: res.headers, text, body: isJson ? JSON.parse(text) : undefined }
48	}
